rulesetGrouping.rbnfRules:
%spellout-numbering-year:
x.x: =0.0=;
0: =%spellout-numbering=;
%spellout-numbering:
0: =%spellout-cardinal-masculine=;
%spellout-cardinal-masculine:
-x: минус >>;
x.x: << кома >>;
0: нула;
1: еден;
2: два;
3: три;
4: четири;
5: пет;
6: шест;
7: седум;
8: осум;
9: девет;
10: десет;
11: единаесет;
12: дванаесет;
13: тринаесет;
14: четиринаесет;
15: петнаесет;
16: шеснаесет;
17: седумнаесет;
18: осумнаесет;
19: деветнаесет;
20: дваесет[ и >>];
30: триесет[ и >>];
40: четириесет[ и >>];
50: педесет[ и >>];
60: шеесет[ и >>];
70: седумдесет[ и >>];
80: осумдесет[ и >>];
90: деведесет[ и >>];
100: <%%hundreds<[ >%%and-masculine>];
1000: илјада[ >%%and-masculine>];
2000: <%spellout-cardinal-feminine< $(cardinal,one{илјада}other{илјади})$[ >%%and-masculine>];
1000000: <%spellout-cardinal-masculine< $(cardinal,one{милион}other{милиони})$[ >%%and-masculine>];
1000000000: <%spellout-cardinal-feminine< $(cardinal,one{милијарда}other{милијарди})$[ >%%and-masculine>];
1000000000000: <%spellout-cardinal-masculine< $(cardinal,one{билион}other{билиони})$[ >%%and-masculine>];
1000000000000000: <%spellout-cardinal-feminine< $(cardinal,one{билијарда}other{билијарди})$[ >%%and-masculine>];
1000000000000000000: =#,##0=;
%spellout-cardinal-neuter:
-x: минус >>;
x.x: << кома >>;
0: нула;
1: едно;
2: две;
3: =%spellout-cardinal-masculine=;
20: дваесет[ и >>];
30: триесет[ и >>];
